import type { AlternativesFeatureCollection } from '../types/alternatives.types'

// Bundled as a static asset, same pattern as municipalProposal.api.ts. Generated by
// scripts/build-alternatives-2026-11.py from the official axis and slide 8.
export async function fetchAlternativesGeometry(): Promise<AlternativesFeatureCollection> {
  const module = await import('../../../data/alternatives-2026-11.geojson?url')
  const response = await fetch(module.default)
  if (!response.ok) {
    throw new Error(`Failed to load November 2026 alternatives geometry: ${response.status}`)
  }
  return response.json() as Promise<AlternativesFeatureCollection>
}
